<script setup lang="ts">
import{computed,onBeforeUnmount,shallowRef,watch}from'vue'
import{api}from'../api/client'
import{can,session,contextGeneration,switchingTenant}from'../stores/session'
import{createRegisteredMonitoring,type RegisteredState}from'../utils/monitoringRegistered'
import{monitoringPresets}from'../utils/monitoringOnboarding'
import ApiErrorNotice from'./ApiErrorNotice.vue'
const state=shallowRef<RegisteredState>({rows:null,busy:null,activeId:null,report:null,error:null,cancelled:false})
const reader=createRegisteredMonitoring(api,s=>state.value=s)
const permitted=computed(()=>session.value?.mode==='remote_test'&&can('assets:read')&&can('configurations:read')&&!switchingTenant.value)
const canTest=computed(()=>permitted.value&&session.value?.user.role==='padmin'&&can('configurations:write'))
watch(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.account_version,session.value?.permission_version,session.value?.user.role,[...(session.value?.capabilities??[])].sort(),permitted.value,canTest.value]),()=>{const s=session.value;reader.reset(permitted.value&&s?{tenantId:s.tenant.id,actorId:s.user.id,permissionVersion:s.permission_version,canTest:canTest.value}:null)},{immediate:true,flush:'sync'})
onBeforeUnmount(reader.dispose)
const title=(id:string)=>monitoringPresets.find(p=>p.id===id)?.title??id
const outcome=computed(()=>state.value.report?({NOT_RUN:'尚未执行协议检测',FAILED:'单次探测失败',TCP_REACHABLE_PROTOCOL_UNVERIFIED:'TCP 可连接；Agent 协议未核验',SAMPLE_VERIFIED_ONCE:'单次样本核验通过'})[state.value.report.probe_status]:'')
</script>
<template><section v-if="permitted" class="registered-monitoring ws-card" aria-labelledby="registered-monitoring-title"><div class="actions"><h2 id="registered-monitoring-title">服务器登记目标</h2><button type="button" :disabled="!!state.busy" @click="reader.load">读取登记目标</button><button v-if="state.busy" type="button" @click="reader.cancel">取消等待</button></div><p v-if="state.busy" role="status">{{state.busy==='list'?'正在读取当前授权目标…':'正在进行一次有界只读探测…'}}</p><p v-if="state.cancelled" role="status">已取消等待，迟到结果不会显示；服务器可能仍在完成单次探测。</p><ApiErrorNotice :error="state.error" :retrying="!!state.busy" retry-label="重新读取登记目标" @retry="reader.load" /><p v-if="state.rows&&!state.rows.length" role="status">当前租户没有已登记监控目标。</p><div v-if="state.rows?.length" class="registered-scroll" role="region" tabindex="0" aria-label="服务器登记监控目标，可横向滚动"><table><caption class="sr-only">只读取与当前授权资产及管理地址一致的登记目标</caption><thead><tr><th scope="col">资产 / 场景</th><th scope="col">采集端点</th><th scope="col">下游目标</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="row in state.rows" :key="row.target_id"><td>{{row.asset_name}}<small>{{title(row.configuration.targets[0]!.preset_id)}}</small></td><td>{{row.configuration.targets[0]!.endpoint}}</td><td>{{row.configuration.targets[0]!.target??'直接采集'}}</td><td><button v-if="canTest" type="button" :disabled="!!state.busy||!row.test_authorized" :aria-label="'测试 '+row.asset_name" @click="reader.probe(row.target_id)">测试连接</button><span v-if="!row.test_authorized">测试授权未配置</span><span v-else-if="!canTest">只有读取权限</span></td></tr></tbody></table></div><div v-if="state.report" class="server-probe-report" role="status"><strong>{{outcome}}</strong><p>目标：{{state.activeId}}</p><p v-if="state.report.reason">原因：{{state.report.reason}}</p><p v-if="state.report.sample_count!==null">样本 {{state.report.sample_count}} 条 · {{state.report.matched_metrics.join('、')}}</p><small>服务器单次结果，不证明持续采集、设备身份或业务健康。</small></div></section></template>
<style scoped>
.registered-monitoring{min-width:0;padding:16px;margin-bottom:12px}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.actions h2{margin:0 auto 0 0}.registered-monitoring button{min-height:44px}.registered-scroll{max-width:100%;overflow:auto;margin-top:12px}.registered-scroll table{width:100%;min-width:700px;border-collapse:collapse;text-align:left}.registered-scroll th,.registered-scroll td{padding:10px;border-bottom:1px solid #e3e9f2;overflow-wrap:anywhere;vertical-align:top}.registered-scroll small{display:block;margin-top:4px}.server-probe-report{margin-top:12px;overflow-wrap:anywhere}.registered-monitoring :focus-visible{outline:2px solid #2165c5;outline-offset:3px}@media(max-width:760px){.registered-monitoring{padding:12px}}
</style>
